// Parity anchor for the app-side type-4 signer and execute() encoder.
// Vectors generated with eth_account 0.13 / eth_abi — the libraries the
// server signs sponsored 7702 transactions with (cusd_plus/sponsor_7702.py).
// Regenerate them with those libraries, never from this file's own output.
import {
  encodeExecuteCalldata,
  signSetCodeAuthorization,
  signSetCodeTransaction,
  selector,
  encodeAddress,
  encodeUint,
} from '../evmWallet';

const PK = '1111111111111111111111111111111111111111111111111111111111111111';
const EOA = '0x19E7E376E7C213B7E7e7e46cc70A5dD086DAff2A';
const HEARTBEAT = '0x' + 'ab'.repeat(20);
const USDT = '0x55d398326f99059fF775485246999027B3197955';
const DEST = '0x' + 'cd'.repeat(20);
const ZERO32 = '0x' + '00'.repeat(32);

const calls = [
  { to: HEARTBEAT, valueWei: 0n, data: selector('assertSilent()') },
  {
    to: USDT,
    valueWei: 0n,
    data: selector('transfer(address,uint256)') + encodeAddress(DEST) + encodeUint(123456789n),
  },
];

const CALLDATA = '';
const CALLDATA_SIGNED = '';
const RAW_TX = '';
const TX_HASH = '0xd5708a25c16e1a1dbb6914385fd81cd95eca5d580f10c496fd281df6f54c7514';

describe('execute() calldata', () => {
  it('matches eth_abi for a self-call (zero nonce/deadline, empty signature)', () => {
    expect(encodeExecuteCalldata(calls, 0n, 0n, ZERO32, '0x')).toBe(CALLDATA);
  });

  it('matches eth_abi with a signature, nonce, deadline and intentId', () => {
    expect(
      encodeExecuteCalldata([calls[0]], 3n, 1800000000n, '0x' + 'aa'.repeat(32), '0x' + 'bb'.repeat(65)),
    ).toBe(CALLDATA_SIGNED);
  });
});

describe('type-4 (EIP-7702) transaction', () => {
  it('signs the same authorization as eth_account', () => {
    const auth = signSetCodeAuthorization('0xc06bd197b34a587026615c6aed21301f5e99bc00', 8n, PK);
    expect(auth.yParity).toBe(0);
    expect(BigInt(auth.r)).toBe(BigInt('0xb32b8bedfd9e8f6bd8610a11aceb37db5bde5b2e10416b3080098045e165adf3'));
    expect(BigInt(auth.s)).toBe(BigInt('0x5ea3bc432bbaa18c1d9d25b935e83b5bc351d5384367b62ecb1f408fe23f07b3'));
  });

  it('produces the same raw bytes and hash as eth_account', () => {
    const auth = signSetCodeAuthorization('0xc06bd197b34a587026615c6aed21301f5e99bc00', 8n, PK);
    const signed = signSetCodeTransaction(
      {
        nonce: 7n,
        maxPriorityFeePerGas: 100_000_000n,
        maxFeePerGas: 120_000_000n,
        gasLimit: 250_000n,
        to: EOA,
        valueWei: 0n,
        data: CALLDATA,
        authorizationList: [auth],
        chainId: 56n,
      },
      PK,
    );
    expect(signed.rawTx).toBe(RAW_TX);
    expect(signed.txHash).toBe(TX_HASH);
  });

  it('refuses a type-4 transaction without an authorization', () => {
    expect(() =>
      signSetCodeTransaction(
        {
          nonce: 0n, maxPriorityFeePerGas: 1n, maxFeePerGas: 1n, gasLimit: 21000n,
          to: EOA, valueWei: 0n, data: '0x', authorizationList: [],
        },
        PK,
      ),
    ).toThrow('type-4 needs an authorization');
  });
});
